<script lang="ts">
 import {goto} from '$app/navigation';import { Save, Check, UserRound, Mail, LockKeyhole, KeyRound, ShieldCheck, Scan, Camera } from 'lucide-svelte';import Protected from '@lib/components/Protected.svelte';import Button from '@lib/components/ui/button.svelte';import {user,settings,setSession} from '@lib/session';import {api,json} from '@lib/api';import type {Settings} from '@lib/types';
 let name=$state(''),oldPassword=$state(''),password=$state(''),confirm=$state(''),error=$state(''),success=$state(''),busy=$state(false),prefs=$state<Settings>({confidence_threshold:.5,visualization_mode:'both',show_confidence:true,preferred_camera:null}),devices=$state<MediaDeviceInfo[]>([]);
 $effect(()=>{if($user)name=$user.full_name;prefs={...$settings};});
 async function action(fn:()=>Promise<void>,message:string){busy=true;error='';success='';try{await fn();success=message;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function saveProfile(e:SubmitEvent){e.preventDefault();await action(async()=>user.set(await api('/users/me',json('PATCH',{full_name:name}))),'Your profile has been updated.');}
 async function saveSettings(e:SubmitEvent){e.preventDefault();await action(async()=>settings.set(await api('/users/settings',json('PATCH',prefs))),'Detection preferences saved.');}
 async function changePassword(e:SubmitEvent){e.preventDefault();if(password!==confirm){error='New passwords do not match.';return;}await action(async()=>{await api('/auth/password',json('PATCH',{current_password:oldPassword,new_password:password}));setSession(null);await goto('/login');},'');}
 async function cameras(){await action(async()=>{const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});try{devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');}finally{stream.getTracks().forEach(t=>t.stop());}},'Available cameras found.');}
</script>
<Protected><div class="page-title"><div><h1>Profile & settings</h1><p>Make this perspective your own.</p></div></div>{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if success}<div class="notice success" role="status"><Check size={17}/>{success}</div>{/if}<div class="settings-row"><div><h2>Your profile</h2><p>Your personal workspace identity.</p></div><form class="panel settings-form" onsubmit={saveProfile}><label>Full name<span class="settings-input"><UserRound size={18} aria-hidden="true"/><input required maxlength="120" autocomplete="name" bind:value={name}/></span></label><label>Email<span class="settings-input"><Mail size={18} aria-hidden="true"/><input value={$user?.email} type="email" disabled/></span></label><p class="field-help">Member since {$user?new Date($user.created_at).toLocaleDateString():''}.</p><Button disabled={busy} type="submit"><Save size={15}/>Save profile</Button></form></div><div class="settings-row"><div><h2>Detection preferences</h2><p>Defaults for new camera and image sessions.</p></div><form class="panel settings-form" onsubmit={saveSettings}><label for="default-confidence">Confidence threshold <strong>{Math.round(prefs.confidence_threshold*100)}%</strong></label><input id="default-confidence" type="range" min=".1" max=".95" step=".05" bind:value={prefs.confidence_threshold}/><label>Visualization mode<span class="settings-input"><Scan size={18} aria-hidden="true"/><select bind:value={prefs.visualization_mode}><option value="box">Bounding boxes</option><option value="mask">Segmentation masks</option><option value="both">Both</option></select></span></label><label class="checkbox-row"><span>Show confidence labels</span><input type="checkbox" bind:checked={prefs.show_confidence}/></label><label>Preferred camera<span class="settings-input"><Camera size={18} aria-hidden="true"/><select bind:value={prefs.preferred_camera}><option value={null}>Device default</option>{#each devices as d}<option value={d.deviceId}>{d.label||'Camera'}</option>{/each}{#if prefs.preferred_camera&&!devices.some(d=>d.deviceId===prefs.preferred_camera)}<option value={prefs.preferred_camera}>Saved camera</option>{/if}</select></span></label><button type="button" class="text-link" onclick={cameras}>Find available cameras</button><Button disabled={busy} type="submit"><Save size={15}/>Save preferences</Button></form></div><div class="settings-row"><div><h2>Account security</h2><p>Changing your password signs out all devices.</p></div><form class="panel settings-form" onsubmit={changePassword}><label>Current password<span class="settings-input"><LockKeyhole size={18} aria-hidden="true"/><input required type="password" autocomplete="current-password" bind:value={oldPassword}/></span></label><label>New password<span class="settings-input"><KeyRound size={18} aria-hidden="true"/><input required minlength="8" maxlength="128" type="password" autocomplete="new-password" bind:value={password}/></span></label><label>Confirm new password<span class="settings-input"><ShieldCheck size={18} aria-hidden="true"/><input required minlength="8" type="password" autocomplete="new-password" bind:value={confirm}/></span></label><Button disabled={busy} variant="outline" type="submit">Change password</Button></form></div></Protected>

<style>
 .settings-input{position:relative;display:block;min-width:0}
 .settings-input :global(>svg){position:absolute;left:15px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}
 .settings-input>input,.settings-input>select{width:100%;padding-left:45px}
 .settings-input:focus-within :global(>svg){color:var(--accent)}
 @media(max-width:540px){.settings-input>input,.settings-input>select{font-size:16px}}
</style>